/**
 * X12 收敛断言（G7-S4）
 * 数据源（model.md）：不变量 INV-8（在册域名必有有效证书）remedy.detection
 * 断言：制造违约 ⇒ 等待 ≤ boundMs ⇒ 状态收敛（检测方式：在册域名证书覆盖与有效期档巡检）
 */
import { describe, it, expect } from '@jest/globals';

describe('X12 收敛断言：INV-8 在册域名必有有效证书', () => {
  it('制造违约后收敛（boundMs=1209600000）', async () => {
    // 制造违约：违反不变量表达式「接入域名.在册状态=在册 ⇒ 存在 有效期档≠已过期 ∧ 域名覆盖=已覆盖 的证书」
    makeViolation('接入域名.在册状态=在册 ⇒ 存在 有效期档≠已过期 ∧ 域名覆盖=已覆盖 的证书');
    // 等待 ≤ 1209600000ms 后断言收敛
    // 收敛断言：检测方式「在册域名证书覆盖与有效期档巡检」
    await expect(converged('在册域名证书覆盖与有效期档巡检')).resolves.toBe(true);
    expect(elapsed()).toBeLessThanOrEqual(1209600000);
  });
});

/**
 * X15 凭证过期必须失效（G7-S6 / P2-6）
 * 数据源（model.md）：credential: 段凭证 域名证书（ttl=由证书自身 notAfter 决定，系统只观测不签发（档位见 域名证书.有效期档））
 * 断言：凭证已过期时验证必须失败（过期 ⇒ 失效，S6-4）
 */
import { describe, it, expect } from '@jest/globals';

describe('X15 凭证过期必须失效：域名证书', () => {
  it('凭证 域名证书 已过期（ttl=由证书自身 notAfter 决定，系统只观测不签发（档位见 域名证书.有效期档））时验证必须失败', () => {
    // 制造过期：把凭证时间推进到 ttl 有效期之后
    makeCredentialExpired('域名证书');
    // 验证凭证：过期 ⇒ 必须失效
    const res = verifyCredential('域名证书');
    expect(res.valid).toBe(false);
  });
});

/**
 * X15 凭证已撤销必须失效（G7-S6 / P2-6）
 * 数据源（model.md）：credential: 段凭证 域名证书（revoke=运维在控制台吊销 ⇒ 数据面停止装载；机构侧吊销本系统不感知）
 * 断言：凭证已撤销时验证必须失败（撤销 ⇒ 失效，S6-4）
 */
import { describe, it, expect } from '@jest/globals';

describe('X15 凭证已撤销必须失效：域名证书', () => {
  it('凭证 域名证书 已撤销（revoke=运维在控制台吊销 ⇒ 数据面停止装载；机构侧吊销本系统不感知）时验证必须失败', () => {
    // 制造撤销：按撤销语义 运维在控制台吊销 ⇒ 数据面停止装载；机构侧吊销本系统不感知 撤销凭证
    makeCredentialRevoked('域名证书');
    // 验证凭证：已撤销 ⇒ 必须失效
    const res = verifyCredential('域名证书');
    expect(res.valid).toBe(false);
  });
});

/**
 * X15 凭证回查失败（G7-S6 / P2-6）
 * 数据源（model.md）：credential: 段凭证 域名证书（selfContained=local-verify）
 * 断言：回查失败时仍验证通过（local-verify，S6-2，fail-open）
 */
import { describe, it, expect } from '@jest/globals';

describe('X15 凭证回查失败：域名证书（local-verify）', () => {
  it('回查失败时验证仍通过（local-verify，fail-open）', () => {
    // 制造回查失败：lookup 端点不可达 / 超时 / 5xx
    simulateLookupFailure('域名证书');
    // local-verify：凭证可本地验证，回查失败不阻断——仍验证通过（S6-2，fail-open）
    const res = verifyCredential('域名证书');
    expect(res.valid).toBe(true);
  });
});
